const props = defineProps<{
  word: string
  num?: number
  isDark?: boolean
}>()

const getLetterSvg = (letter: string, index: number) => {
  const svg = svgMap[letter.toUpperCase()]
  if (!svg) return ''

  let modifiedSvg = svg
  
  // 获取所有 path 标签的 id
  const idMatches = svg.match(/id="([^"]+)"/g) || []
  const ids = idMatches.map(match => match.slice(4, -1))
  
  ids.forEach(id => {
    const isBaseLayer = id === 'word'
    const letterColor = props.isDark ? 'rgba(255,255,255,0.9)' : 'rgba(0,0,0,0.9)'
    const accentColor = 'rgb(0, 122, 255)'
    
    // 在对应 id 的 path 标签中替换 fill 属性
    const pathStart = modifiedSvg.indexOf(`id="${id}"`)
    if (pathStart !== -1) {
      const pathEnd = modifiedSvg.indexOf('/>', pathStart)
      if (pathEnd !== -1) {
        // 提取 path 标签内容
        const pathContent = modifiedSvg.substring(pathStart, pathEnd)
        
        // 移除已有的 fill 属性
        let newPathContent = pathContent.replace(/\s+fill="[^"]*"/g, '')
        
        // 添加新的 fill 属性
        let fillColor = isBaseLayer ? letterColor : 
                       (Number(id) <= props.num! ? accentColor : 'rgba(255, 255, 255, 0)')
        
        newPathContent += ` fill="${fillColor}"`
        
        // 替换原有内容
        modifiedSvg = modifiedSvg.substring(0, pathStart) + 
                     newPathContent + 
                     modifiedSvg.substring(pathEnd)
      }
    }
  })

  return `data:image/svg+xml;base64,${base64Encode(modifiedSvg)}`
}
</script>

